const THRESHOLDS = {
  ROM_DROP_PCT: 15,
  LOW_COMPLETION_PCT: 50,
  RUSHED_REPS_SHARE: 0.5,
  MANY_INCOMPLETE: 3
};

const input = $input.first().json;
const metrics = input.metrics || {};
const history = input.history || [];
const flags = [];

if (metrics.baseline_rom && metrics.rom_vs_target_pct !== undefined) {
  const dropPct = ((metrics.baseline_rom - (metrics.baseline_rom * metrics.rom_vs_target_pct / 100)) / metrics.baseline_rom) * 100;
  if (dropPct > THRESHOLDS.ROM_DROP_PCT) {
    flags.push({
      code: "ROM_DROP",
      severity: "high",
      source: "rule",
      evidence: "mean ROM fell " + Math.round(dropPct) + "% below the 3-session baseline"
    });
  }
}

const currentFaults = Object.keys(metrics.fault_counts || {});
const historyFaultCodes = new Set(history.flatMap(s => Object.keys(s.fault_counts || {})));
for (const fault of currentFaults) {
  if (!historyFaultCodes.has(fault)) {
    flags.push({
      code: "NEW_COMPENSATION",
      severity: "medium",
      source: "rule",
      evidence: fault + " not seen in history"
    });
  }
}

if (metrics.reps_vs_target_pct !== undefined && metrics.reps_vs_target_pct < THRESHOLDS.LOW_COMPLETION_PCT) {
  flags.push({
    code: "LOW_COMPLETION",
    severity: "medium",
    source: "rule",
    evidence: "only " + metrics.reps_vs_target_pct + "% of target reps completed"
  });
}

if (metrics.fast_rep_share !== undefined && metrics.fast_rep_share > THRESHOLDS.RUSHED_REPS_SHARE) {
  flags.push({
    code: "RUSHED_REPS",
    severity: "low",
    source: "rule",
    evidence: Math.round(metrics.fast_rep_share * 100) + "% of reps completed too fast"
  });
}

if ((metrics.incomplete_attempts || 0) >= THRESHOLDS.MANY_INCOMPLETE) {
  flags.push({
    code: "MANY_INCOMPLETE",
    severity: "medium",
    source: "rule",
    evidence: metrics.incomplete_attempts + " incomplete attempts"
  });
}

return [{ json: { ...input, rule_flags: flags } }];
